const std = @import("std");

const Value = union(enum) {
    num: f64,
    str: []const u8,
    obj: struct { keys: [][]const u8, vals: []Value },
};

pub fn main() !void {
    const path = "person.name";

    var parts: [2][]const u8 = undefined;
    var start: usize = 0;
    var idx: usize = 0;
    for (path, 0..) |ch, i| {
        if (ch == '.') {
            parts[idx] = path[start..i];
            idx += 1;
            start = i + 1;
        }
    }
    parts[idx] = path[start..];

    std.debug.print("Path segments: ", .{});
    for (0..idx + 1) |i| {
        std.debug.print("{s} ", .{parts[i]});
    }
    std.debug.print("\n", .{});
}
